// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.proactiveimport timber.log.Timberimport com.roshan.persona.voice.bargein.ProactiveBargeInimport com.roshan.persona.voice.bargein.ProactiveBargeInPriorityimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.time.Durationimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Proactive Engine (§11 Proactive Intelligence). * * The brain behind NOUS speaking *first* — without being prompted by a * wake word. Runs on a periodic schedule (every 5 minutes via WorkManager * per §11) and evaluates all registered triggers; the highest-priority * trigger that passes [shouldSpeak] is spoken via [EmotionalTtsEngine]. * * ## Trigger sources (§11 + §20 v2 fix #7) * *  - **Rule-based** (this class): time, calendar, battery, missed calls, *    weather, health, security, routine. Provided by injected [TriggerSource]s. *  - **Habit-based** ([HabitTracker], v2 fix #7): observed user patterns *    from the Memory Module. e.g. "User opens camera at 8 AM daily" → *    "Shall I open your camera?" * * ## When NOUS does NOT speak (§11 shouldSpeak rules) * *  - User is in a call. *  - User is in a meeting (calendar busy). *  - Silent hours (default 10 PM–7 AM) and trigger priority < 8. *  - Already spoke within the last 5 minutes. *  - User disabled proactive speech in Settings. *  - Trigger's message would be redundant (e.g. already briefed today). * * ## One message per check * * [checkAndSpeak] evaluates all triggers, sorts by priority desc, and * speaks the *first* one that passes [shouldSpeak]. Lower-priority * triggers are skipped (they'll fire on the next check if still relevant). * This prevents NOUS from rapid-fire announcing 5 things at once. * * ## Proactive barge-in (§13) * * Triggers with priority ≥ 8 can proactive-barge-in — interrupt the user * mid-speech — via [ProactiveBargeIn]. This is gated separately by the * [ProactiveBargeIn] class's own cooldown (30 s default) so a single * urgent event doesn't cut the user off repeatedly. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§11 Proactive Intelligence, §25 Q5 silent hours</a> */class ProactiveEngine(    private val tts: EmotionalTtsEngine,    private val proactiveBargeIn: ProactiveBargeIn?,    private val triggerSources: List<TriggerSource>,    private val stateProbe: ProactiveStateProbe,    private val personaProvider: () -> VoicePersona,    private val config: Config = Config(),    private val dispatcher: CoroutineDispatcher,) {    /**     * Configuration for the proactive engine.     *     * @param minIntervalMs     minimum gap between proactive messages     *                            (default 5 minutes per §11).     * @param silentHours       when to suppress non-urgent triggers     *                            (default 10 PM–7 AM per §25 Q5).     * @param proactiveBargeInThreshold  priority required to proactive-barge-in     *                            (default 8 per §13).     */    data class Config(        val minIntervalMs: Long = DEFAULT_MIN_INTERVAL_MS,        val silentHours: SilentHours = SilentHours(),        val proactiveBargeInThreshold: Int = SilentHours.PROACTIVE_BARGE_IN_THRESHOLD,    ) {        init {            require(minIntervalMs >= 0) { "minIntervalMs must be non-negative" }            require(proactiveBargeInThreshold in 1..10) {                "proactiveBargeInThreshold must be 1..10"            }        }        companion object {            const val DEFAULT_MIN_INTERVAL_MS = 5 * 60 * 1000L  // 5 minutes        }    }    private val lastSpokeMs = AtomicLong(0L)    /**     * Run one proactive check.     *     * Called by WorkManager every 5 minutes. Evaluates all [triggerSources],     * filters by [shouldSpeak], and speaks the highest-priority trigger.     *     * @return the trigger that was spoken, or null if nothing fired.     */    suspend fun checkAndSpeak(): ProactiveTrigger? = withContext(dispatcher) {        if (!stateProbe.isProactiveSpeechEnabled()) {            Timber.tag(TAG).d("Proactive speech disabled by user — skipping check.")            return@withContext null        }        val allTriggers = mutableListOf<ProactiveTrigger>()        for (source in triggerSources) {            val triggers = runCatching { source.evaluate() }                .onFailure { Timber.tag(TAG).w("TriggerSource ${source::class} failed.", it) }                .getOrDefault(emptyList())            allTriggers.addAll(triggers)        }        // Sort by priority desc — speak the highest priority that passes shouldSpeak.        for (trigger in allTriggers.sortedByDescending { it.priority }) {            if (shouldSpeak(trigger)) {                speakProactively(trigger)                return@withContext trigger            }        }        null    }    /**     * Decide whether [trigger] should be spoken right now.     *     * Per §11 shouldSpeak rules:     *  - User in call → no.     *  - User in meeting → no.     *  - Silent hours + priority < 8 → no.     *  - Already spoke within [Config.minIntervalMs] → no.     */    internal fun shouldSpeak(trigger: ProactiveTrigger): Boolean {        if (stateProbe.isUserInCall()) return false        if (stateProbe.isUserInMeeting()) return false        if (config.silentHours.isActiveNow() && !trigger.interruptsSilentHours) return false        if (lastSpokeMs.get() != 0L) {            val elapsed = System.currentTimeMillis() - lastSpokeMs.get()            if (elapsed < config.minIntervalMs) return false        }        return true    }    /**     * Speak [trigger] via TTS (or proactive-barge-in if priority is high enough     * and the user was speaking).     */    private suspend fun speakProactively(trigger: ProactiveTrigger) {        val emotion = when (trigger.priority) {            in 8..10 -> Emotion.URGENT            in 5..7 -> Emotion.NEUTRAL            else -> Emotion.CALM        }        val persona = personaProvider()        lastSpokeMs.set(System.currentTimeMillis())        if (trigger.allowsProactiveBargeIn && proactiveBargeIn != null && stateProbe.isUserSpeaking()) {            // Urgent + user is speaking → proactive barge-in.            val priorityEnum = ProactiveBargeInPriority.fromLevel(trigger.priority)                ?: ProactiveBargeInPriority.CRITICAL_REMINDER            proactiveBargeIn.tryBargeIn(                message = trigger.message,                priority = priorityEnum.level,                persona = persona,                stopStt = { stateProbe.stopStt() },                resumeStt = { stateProbe.resumeStt() },            )        } else {            // Normal proactive speak — TTS, no interruption.            tts.speak(                text = trigger.message,                emotion = emotion,                persona = persona,                onDone = {},                onBargeIn = {},            )        }        Timber.tag(TAG).i("Spoke proactively: type=${trigger.type}, priority=${trigger.priority}, emotion=$emotion.")    }    /** Force-reset the last-spoke timestamp (for tests). */    internal fun resetLastSpoke() {        lastSpokeMs.set(0L)    }    private companion object {        private const val TAG = "ProactiveEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** * Source of proactive triggers. * * Implementations include: calendar, battery, missed-calls, weather, health, * security, routine, and [HabitTracker]. The [ProactiveEngine] calls * [evaluate] on each source and merges the results. */fun interface TriggerSource {    /** Evaluate this source and return any triggers that should fire now. */    suspend fun evaluate(): List<ProactiveTrigger>}// ──────────────────────────────────────────────────────────────────────────/** * Probe for runtime state needed by the proactive engine. * * Real implementation reads from system services (TelecomManager for call * state, CalendarProvider for meeting state, STT engine for speaking state). * Tests inject a fake. */interface ProactiveStateProbe {    /** True if the user is currently in a phone call. */    fun isUserInCall(): Boolean    /** True if the user's calendar shows them as busy right now. */    fun isUserInMeeting(): Boolean    /** True if the user is currently speaking (STT is recording voice). */    fun isUserSpeaking(): Boolean    /** True if the user has enabled proactive speech in Settings. */    fun isProactiveSpeechEnabled(): Boolean    /** Stop the STT engine (called before proactive barge-in TTS). */    fun stopStt()    /** Resume the STT engine (called after proactive barge-in TTS completes). */    fun resumeStt()}

